using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SmartCampusServicePortal.Data; using SmartCampusServicePortal.Models; namespace SmartCampusServicePortal.Controllers; public class StudentsController(ApplicationDbContext db):Controller{public async Task<IActionResult> Index()=>View(await db.Students.ToListAsync()); [HttpGet] public IActionResult Register()=>View(new Student()); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Register(Student s){if(await db.Students.AnyAsync(x=>x.StudentIdNumber==s.StudentIdNumber))ModelState.AddModelError("StudentIdNumber","Roll number already exists.");if(!ModelState.IsValid)return View(s);db.Add(s);await db.SaveChangesAsync();TempData["Message"]="Student registered.";return RedirectToAction(nameof(Index));} public async Task<IActionResult> Details(int id){var s=await db.Students.FindAsync(id);if(s==null)return NotFound();ViewBag.Requests=await db.ServiceRequests.Where(x=>x.StudentRollNo==s.StudentIdNumber).ToListAsync();return View(s);} [HttpGet] public async Task<IActionResult> Dashboard(string? rollNo){if(string.IsNullOrWhiteSpace(rollNo))return View();var s=await db.Students.FirstOrDefaultAsync(x=>x.StudentIdNumber==rollNo);if(s==null){ViewBag.ErrorMessage="Student not found.";return View();}return View(await db.ServiceRequests.Where(x=>x.StudentRollNo==s.StudentIdNumber).ToListAsync());}}